var conns = new Dictionary<string, HashSet<string>>();
bool Connect(string u, string c)
{
    if (!conns.TryGetValue(u, out var set))
        conns[u] = set = new();
    set.Add(c);
    return set.Count == 1;
}
bool Disconnect(string u, string c)
{
    conns[u].Remove(c);
    return conns[u].Count == 0;
}
var on = new[] { "t1", "t2", "t3" }
    .Select(t => Connect("an", t));
Console.WriteLine(string.Join(",", on));
var off = new[] { "t1", "t2", "t3" }
    .Select(t => Disconnect("an", t));
Console.WriteLine(string.Join(",", off));

async IAsyncEnumerable<int> Gen(int n, CancellationToken ct = default)
{
    for (var i = 1; i <= n; i++)
    {
        await Task.Delay(1, ct);
        yield return i;
    }
}
var cts = new CancellationTokenSource();
try
{
    await foreach (var x in Gen(5).WithCancellation(cts.Token))
    {
        Console.WriteLine(x);
        if (x == 2) cts.Cancel();
    }
    Console.WriteLine("done");
}
catch (OperationCanceledException)
{ Console.WriteLine("canceled"); }
